#nullable enable // autogenerated

using System.Collections.Generic;
using MVZ2.Vanilla.Properties;
using MVZ2Logic;
using PVZEngine.Auras;
using PVZEngine.Buffs;
using PVZEngine.Definitions;
using PVZEngine.Tools.Timing;

namespace MVZ2.GameContent.Buffs.Level
{
    [AutoBuffDefinition(VanillaBuffNames.Level.temperance)]
    public class TemperanceBuff : BuffDefinition
    {
        public TemperanceBuff(string nsp, string name) : base(nsp, name)
        {
            AddAura(new BlueprintAura());
        }
        public override void PostAdd(Buff buff)
        {
            base.PostAdd(buff);
            buff.SetProperty(PROP_TIMER, new FrameTimer(MAX_TIMEOUT));
        }
        public override void PostUpdate(Buff buff)
        {
            base.PostUpdate(buff);
            var timer = buff.GetProperty<FrameTimer>(PROP_TIMER);
            if (timer == null)
            {
                buff.Remove();
                return;
            }
            if (timer.RunToExpired())
            {
                buff.Remove();
            }
        }
        public static readonly VanillaBuffPropertyMeta<FrameTimer> PROP_TIMER = new VanillaBuffPropertyMeta<FrameTimer>("Timer");
        public const int MAX_TIMEOUT = 900;

        public class BlueprintAura : AuraEffectDefinition
        {
            public BlueprintAura() : base(VanillaBuffID.SeedPack.temperanceCostReduction, 4)
            {
            }

            public override void GetAuraTargets(AuraEffect auraEffect, List<IBuffTarget> results)
            {
                var level = auraEffect.Source.GetLevel();
                using var seedPacksItem = level.GetAllSeedPacksDisposeable();
                foreach (var seed in seedPacksItem.Value)
                {
                    if (seed == null)
                        continue;
                    results.Add(seed);
                }
            }
        }
    }
}
